"use strict";(globalThis.webpackChunkgrc||=[]).push([[59217],{7045(e){e.exports=JSON.parse('{"citeKey":"he2020optimizingparallel","slug":"he-2020-optimizing-parallel-5527","title":"Optimizing Parallel I/O Accesses through Pattern-Directed and Layout-Aware Replication","authors":["S. He","Y. Yin","X.-H. Sun","X. Zhang","Z. Li"],"venue":"IEEE Transactions on Computers (TC\'20), vol 69. no 2. pp 212-225","type":"Journal","entryType":"article","date":"February, 2020","year":2020,"era":"iit","month":2,"doi":"10.1109/tc.2019.2946135","abstract":"As the performance gap between processors and storage devices keeps increasing, I/O performance becomes a critical bottleneck of modern high-performance computing systems. In this paper, we propose a pattern-directed and layout-aware data replication design, named PDLA, to improve the performance of parallel I/O systems. PDLA includes an HDD-based scheme H-PDLA and an SSD-based scheme S-PDLA. For applications with relatively low I/O concurrency, H-PDLA identifies access patterns of applications and makes a reorganized data replica for each access pattern on HDD-based servers with an optimized data layout. Moreover, to accommodate applications with high I/O concurrency, S-PDLA replicates critical access patterns that can bring performance benefits on SSD-based servers or on HDD-based and SSD-based servers. We have implemented the proposed replication scheme under MPICH2 library on top of OrangeFS file system. Experimental results show that H-PDLA can significantly improve the original parallel I/O system performance and demonstrate the advantages of S-PDLA over H-PDLA.","hasAbstract":true,"lede":"We propose a pattern-directed and layout-aware data replication design, named PDLA, to improve the performance of parallel I/O systems.","links":{"pdf":"https://grc.iit.edu/papers/2020/he-2020-optimizing-parallel-5527.pdf"},"tags":["Parallel I/O","I/O Optimization","Data Replication","Data Reorganization","Data Access Pattern"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);